action.mutation:
mutation CreateProduct($payload: [ProductCreatePayloadInput!]!) {
  mutation: createProduct(payload: $payload) {
    id
    code
  }
}

dataTransform.transform:
[edges.node~>|$|{
  "unitDisplay": unit.name ? unit.name & " (" & unit.code & ")" : "N/A",
  "createdByDisplay": createdByUser.firstName & ' ' & createdByUser.lastName,
  "activeColor": (
    $activeColors := {"true": "#2e7d32", "false": "#d32f2f"};
    $lookup($activeColors, $string(isActive)) ? $lookup($activeColors, $string(isActive)) : "#757575"
  ),
  "yieldColor": (
    targetYield >= 98.5 ? "#2e7d32" : (targetYield >= 95 ? "#ed6c02" : "#d32f2f")
  ),
  "activeDisplay": isActive ? "Active" : "Inactive"
}|]

action.query:
query GetProduct($where: ProductWhereInput) {
  query: product(where: $where) {
    edges {
      node {
        id
        code
        name
        description
        productFamily
        unitId
        unit {
          id
          name
          code
        }
        standardCycleTime
        targetYield
        setupTime
        isActive
        createdAt
        createdByUser {
          id
          firstName
          lastName
        }
      }
    }
  }
}

